import struct
import sys
import unittest
from pathlib import Path

sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'backend'))
import crypto
from audio import PCMDecoder

KEY=bytes(range(32))
# Independent Node.js crypto fixture, not generated by this implementation.
WIRE=bytes.fromhex('80640001000003c012345678e10f744802e89a8952369e33bc88d09a708caf05f45308f9cc9ee186c33d9bec0700000000000000')
PCM_BE=bytes.fromhex('1000f0002000e0003000d0004000c000')
PCM_LE=bytes.fromhex('001000f0002000e0003000d0004000c0')

def packet(pcm=PCM_BE,timestamp=960,sequence=1,counter=7,first=0x80):
 header=struct.pack('>BBHII',first,100,sequence,timestamp,0x12345678)
 tail=struct.pack('<Q',counter)
 return header+crypto.encrypt(KEY,b'\0'*4+tail,pcm,header[4:12])+tail

class AudioTest(unittest.TestCase):
 def test_independent_fixture_decrypts_exact_pcm_and_metadata(self):
  d=PCMDecoder(KEY,0x8000)
  self.assertEqual((d.rate,d.channels),(48000,2))
  self.assertEqual(d.decode(WIRE),{'pcm':PCM_LE,'timestamp':960,'sequence':1,'reset':True,'sampleFrames':4,'nonzeroSamples':8})

 def test_all_exact_pcm_formats_and_invalid_formats(self):
  formats={0x4:(8000,1),0x8:(8000,2),0x10:(16000,1),0x20:(16000,2),0x40:(24000,1),0x80:(24000,2),0x100:(32000,1),0x200:(32000,2),0x400:(44100,1),0x800:(44100,2),0x4000:(48000,1),0x8000:(48000,2)}
  for bits,expected in formats.items():
   d=PCMDecoder(KEY,bits);self.assertEqual((d.rate,d.channels),expected)
  for bits in (0,0xc000,0x400000,0x10000000,-1,True,32768.0,'32768'):
   with self.subTest(bits=bits),self.assertRaises(ValueError):PCMDecoder(KEY,bits)
  for key in (b'',bytes(31),bytes(33),bytearray(KEY),None):
   with self.subTest(key=key),self.assertRaises(ValueError):PCMDecoder(key,0x8000)

 def test_authentication_tampering_does_not_advance_state(self):
  for position in (4,8,12,len(WIRE)-9,len(WIRE)-8):
   d=PCMDecoder(KEY,0x8000);tampered=bytearray(WIRE);tampered[position]^=1
   with self.subTest(position=position),self.assertRaises(ValueError):d.decode(bytes(tampered))
   self.assertTrue(d.decode(WIRE)['reset'])

 def test_replay_rejected_even_with_changed_unauthenticated_sequence(self):
  d=PCMDecoder(KEY,0x8000);d.decode(WIRE)
  replay=bytearray(WIRE);replay[2:4]=b'\xff\xff'
  for wire in (WIRE,bytes(replay),packet(counter=6,timestamp=964)):
   with self.assertRaisesRegex(ValueError,'nonce'):d.decode(wire)
  result=d.decode(packet(counter=8,timestamp=964,sequence=2))
  self.assertFalse(result['reset'])

 def test_bad_pcm_alignment_and_empty_payload_do_not_consume_nonce(self):
  d=PCMDecoder(KEY,0x8000)
  for pcm in (b'',b'\x01',b'\x00\x01',b'\x00'*6):
   with self.assertRaisesRegex(ValueError,'PCM'):d.decode(packet(pcm))
  self.assertTrue(d.decode(WIRE)['reset'])

 def test_fixed_rtp_header_and_datagram_bounds(self):
  for first in (0x40,0xc0,0xa0,0x90,0x81):
   with self.assertRaisesRegex(ValueError,'RTP'):PCMDecoder(KEY,0x8000).decode(packet(first=first))
  for wire in (b'',WIRE[:35],bytes(16384+37)):
   with self.assertRaisesRegex(ValueError,'packet'):PCMDecoder(KEY,0x8000).decode(wire)
  maximal=PCMDecoder(KEY,0x8000).decode(packet(bytes(16384)))
  self.assertEqual((maximal['sampleFrames'],maximal['nonzeroSamples']),(4096,0))

 def test_timestamp_continuity_wrap_and_discontinuity(self):
  d=PCMDecoder(KEY,0x8000)
  self.assertTrue(d.decode(packet(timestamp=0xfffffffc,counter=1))['reset'])
  self.assertFalse(d.decode(packet(timestamp=0,sequence=65535,counter=2))['reset'])
  self.assertFalse(d.decode(packet(timestamp=4,sequence=0,counter=3))['reset'])
  self.assertTrue(d.decode(packet(timestamp=20,counter=4))['reset'])
  self.assertFalse(d.decode(packet(timestamp=24,counter=5))['reset'])

 def test_zero_count_and_signed_extremes(self):
  d=PCMDecoder(KEY,0x4000)
  result=d.decode(packet(struct.pack('>hhhhh',0,-32768,32767,-1,0)))
  self.assertEqual(result['pcm'],struct.pack('<hhhhh',0,-32768,32767,-1,0))
  self.assertEqual((result['sampleFrames'],result['nonzeroSamples']),(5,3))

if __name__=='__main__':unittest.main()
